#include <bits/stdc++.h>
using namespace std;
// t[c][i]: number of characters strictly greater than letter c among the first i characters of s.
static vector<vector<int>> tables(const string &s) {
    vector<vector<int>> t(26, vector<int>(s.size() + 1, 0));
    for (int c = 0; c < 26; c++)
        for (size_t i = 0; i < s.size(); i++) t[c][i + 1] = t[c][i] + (s[i] - 'a' > c);
    return t;
}
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    string a, b; cin >> a >> b;
    int n = a.size(), m = b.size();
    auto A = tables(a), B = tables(b);
    vector<long long> prev(m + 1, 0), cur(m + 1, 0);
    for (int j = 1; j <= m; j++) prev[j] = prev[j - 1] + B[b[j - 1] - 'a'][j - 1];
    for (int i = 1; i <= n; i++) {
        int c = a[i - 1] - 'a';
        cur[0] = prev[0] + A[c][i - 1];
        for (int j = 1; j <= m; j++) {
            int e = b[j - 1] - 'a';
            cur[j] = min(prev[j] + A[c][i - 1] + B[c][j], cur[j - 1] + A[e][i] + B[e][j - 1]);
        }
        swap(prev, cur);
    }
    cout << prev[m] << "\n";
}

