final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

// tables(s)[c][i]: number of characters strictly greater than letter c among the first i characters of s.
func tables(s string) [][]int {
	t := make([][]int, 26)
	for c := 0; c < 26; c++ {
		t[c] = make([]int, len(s)+1)
		for i := 0; i < len(s); i++ {
			t[c][i+1] = t[c][i]
			if int(s[i]-'a') > c {
				t[c][i+1]++
			}
		}
	}
	return t
}

func main() {
	a, b := readToken(), readToken()
	n, m := len(a), len(b)
	A, B := tables(a), tables(b)
	prev := make([]int, m+1)
	cur := make([]int, m+1)
	for j := 1; j <= m; j++ {
		prev[j] = prev[j-1] + B[b[j-1]-'a'][j-1]
	}
	for i := 1; i <= n; i++ {
		c := a[i-1] - 'a'
		cur[0] = prev[0] + A[c][i-1]
		for j := 1; j <= m; j++ {
			e := b[j-1] - 'a'
			cur[j] = min(prev[j]+A[c][i-1]+B[c][j], cur[j-1]+A[e][i]+B[e][j-1])
		}
		prev, cur = cur, prev
	}
	fmt.Println(prev[m])
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
